class Solution {
    vector<int> tree;
    int m;

    void update(int node, int start, int end, int idx, int val) {
        if (start == end) {
            tree[node] = max(tree[node], val);
            return;
        }
        int mid = (start + end) / 2;
        if (idx <= mid) {
            update(2 * node, start, mid, idx, val);
        } else {
            update(2 * node + 1, mid + 1, end, idx, val);
        }
        tree[node] = max(tree[2 * node], tree[2 * node + 1]);
    }

    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) {
            return -1;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        int p1 = query(2 * node, start, mid, l, r);
        int p2 = query(2 * node + 1, mid + 1, end, l, r);
        return max(p1, p2);
    }

public:
    int maximumJumps(vector<int>& nums, int target) {
        int n = nums.size();
        vector<long long> coords;
        for (int i = 0; i < n; ++i) {
            coords.push_back(nums[i]);
            coords.push_back((long long)nums[i] - target);
            coords.push_back((long long)nums[i] + target);
        }
        sort(coords.begin(), coords.end());
        coords.erase(unique(coords.begin(), coords.end()), coords.end());
        m = coords.size();
        tree.assign(4 * m, -1);

        int dp = -1;
        for (int j = 0; j < n; ++j) {
            long long L = (long long)nums[j] - target;
            long long R = (long long)nums[j] + target;

            int idxL = lower_bound(coords.begin(), coords.end(), L) - coords.begin();
            int idxR = upper_bound(coords.begin(), coords.end(), R) - coords.begin() - 1;

            dp = -1;
            if (j == 0) {
                dp = 0;
            } else if (idxL <= idxR) {
                int max_prev = query(1, 0, m - 1, idxL, idxR);
                if (max_prev != -1) {
                    dp = max_prev + 1;
                }
            }

            if (dp != -1) {
                int pos = lower_bound(coords.begin(), coords.end(), (long long)nums[j]) - coords.begin();
                update(1, 0, m - 1, pos, dp);
            }
        }

        return dp;
    }
};
